CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, phone TEXT UNIQUE, name TEXT, role TEXT NOT NULL, salt TEXT, password TEXT);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id BIGINT REFERENCES users(id),expires DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS codes(phone TEXT PRIMARY KEY,digest TEXT,expires DOUBLE PRECISION,sent DOUBLE PRECISION,attempts INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS sms_limits(ip TEXT,stamp DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS children(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,owner BIGINT REFERENCES users(id),name TEXT,sex TEXT,birth TEXT,allergies TEXT,feeding TEXT,history TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS measurements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,child_id BIGINT REFERENCES children(id),day TEXT,height DOUBLE PRECISION,weight DOUBLE PRECISION,source TEXT,created_by BIGINT,UNIQUE(child_id,day));
CREATE TABLE IF NOT EXISTS questionnaires(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,child_id BIGINT REFERENCES children(id),kind TEXT,version TEXT,status TEXT,answers TEXT,created TEXT,created_by BIGINT);
CREATE TABLE IF NOT EXISTS assessments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,child_id BIGINT REFERENCES children(id),summary TEXT,attention TEXT,created TEXT,created_by BIGINT);
CREATE TABLE IF NOT EXISTS plans(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,child_id BIGINT REFERENCES children(id),goal TEXT,diet TEXT,guidance TEXT,next_date TEXT,created TEXT,created_by BIGINT);
CREATE TABLE IF NOT EXISTS tasks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,child_id BIGINT REFERENCES children(id),title TEXT,due TEXT,status TEXT,created TEXT,result TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS risks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,child_id BIGINT REFERENCES children(id),reason TEXT,status TEXT,owner BIGINT REFERENCES users(id),due TEXT,result TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS messages(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,child_id BIGINT REFERENCES children(id),user_id BIGINT REFERENCES users(id),body TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT,action TEXT,child_id BIGINT,created TEXT);
CREATE TABLE IF NOT EXISTS login_limits(ip TEXT,stamp DOUBLE PRECISION);
CREATE INDEX IF NOT EXISTS children_owner_idx ON children(owner);
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(expires);
CREATE INDEX IF NOT EXISTS sms_limits_ip_stamp_idx ON sms_limits(ip,stamp);
CREATE INDEX IF NOT EXISTS login_limits_ip_stamp_idx ON login_limits(ip,stamp);
CREATE INDEX IF NOT EXISTS questionnaires_child_idx ON questionnaires(child_id,id DESC);
CREATE INDEX IF NOT EXISTS assessments_child_idx ON assessments(child_id,id DESC);
CREATE INDEX IF NOT EXISTS plans_child_idx ON plans(child_id,id DESC);
CREATE INDEX IF NOT EXISTS tasks_child_status_idx ON tasks(child_id,status);
CREATE INDEX IF NOT EXISTS risks_child_status_idx ON risks(child_id,status);
CREATE INDEX IF NOT EXISTS messages_child_idx ON messages(child_id,id);
CREATE INDEX IF NOT EXISTS audit_child_idx ON audit(child_id,id DESC);
